create extension if not exists pgcrypto;
create table if not exists employees (key text primary key check(key in ('svetlana','richard','anastasia','jean-claude','kevin')), name text not null, role text not null check(role in ('manager','sales','expense')));
insert into employees(key,name,role) values ('svetlana','Svetlana de Monte Carlo','manager'),('richard','Richard Darling','sales'),('anastasia','Anastasia Ferrari','sales'),('jean-claude','Jean-Claude Bērziņš','sales'),('kevin','Kevin von Whatever','expense') on conflict(key) do update set name=excluded.name,role=excluded.role;
create table if not exists telegram_links (telegram_user_id text primary key, employee_key text not null references employees(key), chat_id text not null, updated_at timestamptz not null default now());
create table if not exists sales (reference text primary key, submitted_at timestamptz not null default now(), submitter text not null references employees(key), origin_channel text not null check(origin_channel in ('web','telegram')), origin_chat_id text, customer text not null, project text not null check(project in ('A','B')), description text not null, amount_cents bigint not null check(amount_cents>0), proposed_split jsonb not null, final_split jsonb, status text not null check(status in ('PENDING','APPROVED')) default 'PENDING', commission_pool_cents bigint, commission_richard_cents bigint, commission_anastasia_cents bigint, commission_jean_claude_cents bigint, decided_at timestamptz, decided_by text references employees(key), check ((proposed_split->>'richard')::int between 0 and 100 and (proposed_split->>'anastasia')::int between 0 and 100 and (proposed_split->>'jean-claude')::int between 0 and 100 and (proposed_split->>'richard')::int+(proposed_split->>'anastasia')::int+(proposed_split->>'jean-claude')::int=100));
create table if not exists expenses (reference text primary key, submitted_at timestamptz not null default now(), reporter text not null references employees(key), origin_channel text not null check(origin_channel in ('web','telegram')), origin_chat_id text, description text not null, category text not null check(category in ('Materials','Travel','Other')), amount_cents bigint not null check(amount_cents>0), proposed_allocation text not null check(proposed_allocation in ('A','B','OVERHEAD')), final_allocation text check(final_allocation in ('A','B','OVERHEAD')), status text not null check(status in ('AWAITING_ALLOCATION','ALLOCATED')), decided_at timestamptz, decided_by text references employees(key));
create table if not exists integration_deliveries (kind text not null check(kind in ('SHEETS','TELEGRAM')), record_type text not null, reference text not null, status text not null check(status in ('PENDING','FAILED','SENT')), attempts int not null default 0, last_error text, updated_at timestamptz not null default now(), primary key(kind,record_type,reference));
create table if not exists telegram_sessions (telegram_user_id text primary key, chat_id text not null, state text not null, payload jsonb not null default '{}', updated_at timestamptz not null default now());
create table if not exists processed_telegram_updates (update_id bigint primary key, processed_at timestamptz not null default now());
alter table employees enable row level security; alter table telegram_links enable row level security; alter table sales enable row level security; alter table expenses enable row level security; alter table integration_deliveries enable row level security; alter table telegram_sessions enable row level security; alter table processed_telegram_updates enable row level security;
